class Pipeline:
    def run(self, data):
        self._validate()
        return self._execute(data)

    def _validate(self):
        if not self._steps:
            raise ValueError('No steps')

    def _execute(self, data):
        self._steps = []
        for step in self._steps:
            data = step(data)
        return data

    def add_step(self, fn):
        if not hasattr(self, '_steps'):
            self._steps = []
        self._steps.append(fn)
